419	impl Element for TextElement {
420	    type RequestLayoutState = ();
421	    type PrepaintState = PrepaintState;
422	
423	    fn id(&self) -> Option<ElementId> {
424	        None
425	    }
426	
427	    fn source_location(&self) -> Option<&'static core::panic::Location<'static>> {
428	        None
