741	            .unwrap();
742	        let view = window.update(cx, |_, _, cx| cx.entity()).unwrap();
743	        cx.observe_keystrokes(move |ev, _, cx| {
744	            view.update(cx, |view, cx| {
745	                view.recent_keystrokes.push(ev.keystroke.clone());
746	                cx.notify();
747	            })
748	        })
749	        .detach();
